#!/bin/bash
# s2_deploy22.sh: медиа-страницы S2 (cinema/music/news/studio) + сбор каталогов. Бэкапы *.bak_s2_1
S=/workspace/nox/web/site; set -u
df -h /workspace | tail -1
for f in cinema.html music.html news.html studio.html creative.html tv.html board.html; do [ -f $S/$f.bak_s2_1 ] || cp $S/$f $S/$f.bak_s2_1; done
mkdir -p $S/data /workspace/nox/state/cinema_catalog /workspace/nox/tools
base64 -d > $S/nox-s2.css <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-cinema.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-music.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-news.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-photo.css <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-photo.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-creative.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-depth.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-board.js <<'B64EOF'

B64EOF
base64 -d > $S/board.html <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-tv.css <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-tv.js <<'B64EOF'

B64EOF
base64 -d > $S/creative.html <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-studio.js <<'B64EOF'

B64EOF
base64 -d > $S/cinema.html <<'B64EOF'

B64EOF
base64 -d > $S/music.html <<'B64EOF'

B64EOF
base64 -d > $S/news.html <<'B64EOF'

B64EOF
base64 -d > $S/studio.html <<'B64EOF'

B64EOF
base64 -d > /workspace/nox/tools/s2_feeds.py <<'B64EOF'

B64EOF
python3 - <<'PY'
import re
S='/workspace/nox/web/site/'
old=open(S+'music.html.bak_s2_1',encoding='utf-8').read()
m=re.search(r'(<section class="card"><h2>Служба.*?)</div></main>',old,re.S)
new=open(S+'music.html',encoding='utf-8').read()
blk='<div id="muOld" hidden>'+(m.group(1) if m else '')+'</div>'
new=new.replace('<!--S2_KEEP_OLD-->',blk).replace('<script type="module" src="./nox-nav.js"></script>','<script type="module" src="./nox-nav.js"></script>\n<script type="module" src="./nox-p-media.js"></script>',1)
open(S+'music.html','w',encoding='utf-8').write(new)
print('music old block',bool(m),len(blk))
PY
python3 - <<'PY'
S='/workspace/nox/web/site/'
import shutil,os
if not os.path.exists(S+'photo.html.bak_s2_1'): shutil.copy(S+'photo.html',S+'photo.html.bak_s2_1')
t=open(S+'photo.html',encoding='utf-8').read()
if 'nox-s2-photo.css' not in t:
    t=t.replace('</head>','<link rel="stylesheet" href="./nox-s2-photo.css?v=1">\n</head>',1).replace('</body>','<script src="./nox-s2-photo.js?v=1" defer></script>\n</body>',1)
    open(S+'photo.html','w',encoding='utf-8').write(t); print('photo patched')
PY
python3 - <<'PY'
S='/workspace/nox/web/site/'
t=open(S+'tv.html',encoding='utf-8').read()
if 'nox-s2-tv.js' not in t:
    t=t.replace('</head>','<link rel="stylesheet" href="./nox-s2-tv.css?v=1">\n</head>',1) if '</head>' in t else t
    t=t.replace('</body>','<script src="./nox-s2-tv.js?v=1" defer></script>\n</body>',1)
    open(S+'tv.html','w',encoding='utf-8').write(t); print('tv patched', 'nox-s2-tv.css' in t)
PY
python3 - <<'PY'
import shutil,os
S='/workspace/nox/web/site/'
if not os.path.exists(S+'editor.html.bak_s2_1'): shutil.copy(S+'editor.html',S+'editor.html.bak_s2_1')
t=open(S+'editor.html',encoding='utf-8').read()
if 'creative.html' not in t:
    t=t.replace('<head>','<head>\n<meta http-equiv="refresh" content="0;url=creative.html"><script>location.replace("creative.html")</script>',1)
    open(S+'editor.html','w',encoding='utf-8').write(t); print('editor redirect')
PY
mkdir -p $S/qa/rework; for p in cinema music news studio photo creative tv board; do cp $S/$p.html $S/qa/rework/$p.fixed; done; ls $S/qa/rework | grep fixed
cd /workspace/nox/tools
pgrep -f "s2_feeds.py loop" >/dev/null || { nohup setsid python3 /workspace/nox/tools/s2_feeds.py loop >> /workspace/nox/svc/logs/s2_feeds.log 2>&1 < /dev/null & }
sleep 1; pgrep -fa s2_feeds | head -2
for p in cinema music news studio; do printf "$p "; curl -s -o /dev/null -w "%{http_code} %{size_download}\n" http://127.0.0.1:8091/$p.html; done
ls -la $S/data | head; df -h /workspace | tail -1
